namespace sv_4359b628c32b4e789b9cb90be615d37b.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    DateTimeOffset Timestamp,
    string Description,
    string Location);

using sv_4359b628c32b4e789b9cb90be615d37b.Client.Models;

namespace sv_4359b628c32b4e789b9cb90be615d37b.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_4359b628c32b4e789b9cb90be615d37b.Client.Models;

namespace sv_4359b628c32b4e789b9cb90be615d37b.Client.Services;

/// <summary>
/// Used when running on WebAssembly — calls the server API over HTTP.
/// </summary>
public sealed class HttpShipmentService(HttpClient httpClient) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await httpClient.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

using sv_4359b628c32b4e789b9cb90be615d37b.Client.Models;
using sv_4359b628c32b4e789b9cb90be615d37b.Client.Services;

namespace sv_4359b628c32b4e789b9cb90be615d37b.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with fake data.
/// </summary>
public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            TrackingNumber: "TRK-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 14, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 7, 9, 8, 30, 0, TimeSpan.FromHours(-5)), "Package picked up", "New York, NY"),
                new StatusUpdate(new DateTimeOffset(2026, 7, 10, 14, 15, 0, TimeSpan.FromHours(-5)), "Arrived at sorting facility", "Philadelphia, PA"),
                new StatusUpdate(new DateTimeOffset(2026, 7, 11, 6, 45, 0, TimeSpan.FromHours(-5)), "In transit to next facility", "Chicago, IL"),
            ]),

        ["TRK-002"] = new Shipment(
            TrackingNumber: "TRK-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 10, 12, 0, 0, TimeSpan.FromHours(-7)),
            StatusUpdates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 7, 7, 9, 0, 0, TimeSpan.FromHours(-7)), "Package picked up", "Los Angeles, CA"),
                new StatusUpdate(new DateTimeOffset(2026, 7, 8, 11, 30, 0, TimeSpan.FromHours(-7)), "Arrived at local facility", "San Francisco, CA"),
                new StatusUpdate(new DateTimeOffset(2026, 7, 9, 10, 20, 0, TimeSpan.FromHours(-7)), "Out for delivery", "San Francisco, CA"),
                new StatusUpdate(new DateTimeOffset(2026, 7, 9, 14, 5, 0, TimeSpan.FromHours(-7)), "Delivered", "San Francisco, CA"),
            ]),

        ["TRK-003"] = new Shipment(
            TrackingNumber: "TRK-003",
            Status: "Processing",
            Location: "Dallas, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 18, 15, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 7, 11, 7, 0, 0, TimeSpan.FromHours(-5)), "Order received", "Dallas, TX"),
            ]),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_4359b628c32b4e789b9cb90be615d37b.Client.Models
@using sv_4359b628c32b4e789b9cb90be615d37b.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>...</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-message">
        <p>@_errorMessage</p>
        <button @onclick="RetryLoad">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="not-found">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>
            <dt>Location</dt>
            <dd>@_shipment.Location</dd>
            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status History</h3>
        <ul class="status-updates">
            @foreach (var update in _shipment.StatusUpdates)
            {
                <li>
                    <time datetime="@update.Timestamp.ToString("o")">@update.Timestamp.ToString("g")</time>
                    &mdash; <strong>@update.Description</strong> (@update.Location)
                </li>
            }
        </ul>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any previous in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _errorMessage = null;
        _shipment = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed — silently abort
            return;
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException || ex.CancellationToken != ct)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryLoad()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

